import{_ as o,C as t,o as s,c as i,E as n,a2 as d}from"./chunks/framework.BOeh4kYD.js";const l="/joinwell52/assets/current-context-20260916/session-without-old-keys.figure.en.svg",y=JSON.parse('{"title":"Resume the conversation. Keep the old credentials too?","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Resume the conversation. Keep the old credentials too?","date":"2026-09-16","published_date":"2026-09-16","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Resume the conversation. Keep the old credentials too?","summary":"A conversation needs continuity, but its launch credentials need not be permanent. A real-file experiment shows why resuming with a new value does not erase the old one on disk.","cover":"/assets/current-context-20260916/session-without-old-keys.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded experiments on pinned source; scope in article","pageClass":"current-context-article"},"headers":[],"relativePath":"en/engineering/2026-09-16-session-without-old-keys.md","filePath":"en/engineering/2026-09-16-session-without-old-keys.md","lastUpdated":1789531953000}'),c={name:"en/engineering/2026-09-16-session-without-old-keys.md"};function h(p,e,u,g,m,v){const a=t("ArticleCover"),r=t("ArticleTableScroll");return s(),i("div",null,[n(a,{image:"/assets/current-context-20260916/session-without-old-keys.cover-v1.png",kicker:"Open-source engineering · Experiments",title:"Resume the conversation. Keep the old credentials too?",summary:"A conversation needs continuity, but its launch credentials need not be permanent. A real-file experiment shows why resuming with a new value does not erase the old one on disk.",version:"2026-09-16",languageHref:"/zh/engineering/2026-09-16-session-without-old-keys",languageLabel:"中文"}),n(r,{language:"en"}),e[0]||(e[0]=d('<h1 id="resume-the-conversation-keep-the-old-credentials-too" tabindex="-1">Resume the conversation. Keep the old credentials too? <a class="header-anchor" href="#resume-the-conversation-keep-the-old-credentials-too" aria-label="Permalink to &quot;Resume the conversation. Keep the old credentials too?&quot;">​</a></h1><p>Saving an AI conversation lets you continue tomorrow. Keeping its history is easy to understand.</p><p>But should the key used to launch the assistant stay with it?</p><p>Here, a key is a credential the application uses to access a service. After an account or connection change, the current run may already use a different credential. <strong>Our real-file experiment showed an easily missed state: resume used the current value while the old value remained in the file on disk.</strong></p><p>“It works again” does not answer “were the earlier copies cleaned up?”</p><h2 id="how-did-a-key-get-into-a-conversation-record" tabindex="-1">How did a key get into a conversation record? <a class="header-anchor" href="#how-did-a-key-get-into-a-conversation-record" aria-label="Permalink to &quot;How did a key get into a conversation record?&quot;">​</a></h2><p>The source is <a href="https://github.com/paperclipai/paperclip/pull/13498" target="_blank" rel="noreferrer">Paperclip #13498</a>, submitted by electrumnz. Paperclip is an open-source application for coordinating AI assistants. This proposed fix was still open when researched.</p><p>When launching an assistant, an application supplies settings called environment variables. Some can contain service credentials. Upstream reports that this launch environment was saved along with session settings, turning values prepared for a run into potentially long-lived copies.</p><p>That interested us because “save more so we can resume later” sounds reasonable. Yet history and credentials serve different purposes. Continuing yesterday&#39;s conversation need not require yesterday&#39;s credential.</p><p>The candidate separates them: remove the launch environment when saving, and supply the current environment when resuming. We narrowed our experiment to a practical question: does that preserve the conversation, and what happens to old values already on disk?</p><h2 id="synthetic-keys-real-files" tabindex="-1">Synthetic keys, real files <a class="header-anchor" href="#synthetic-keys-real-files" aria-label="Permalink to &quot;Synthetic keys, real files&quot;">​</a></h2><p>We used recognizable synthetic strings in place of credentials and read no real keys. The candidate&#39;s save and load code was connected to temporary files. We supplied an old value, resumed with another current value, and inspected what remained in the file.</p><table tabindex="0"><thead><tr><th>Operation</th><th>Old synthetic value remains on disk</th><th>Resume uses current value</th></tr></thead><tbody><tr><td>Save the original record without filtering</td><td>Yes</td><td>Yes; load still uses candidate code</td></tr><tr><td>Save a new record through candidate code</td><td><strong>No</strong></td><td>Yes</td></tr><tr><td>Read a legacy record without saving again</td><td><strong>Yes</strong></td><td>Yes</td></tr><tr><td>Read legacy record, then save through candidate code</td><td><strong>No</strong></td><td>Yes</td></tr></tbody></table><p>All four preserved conversation history. The original object supplied to save also stayed unchanged: removing the environment from the disk copy did not modify data the running session might still need in memory.</p><p>The third row is worth pausing over. Resume received the current value, while inspection still found the old value on disk. Both observations were correct; they looked in different places.</p><p><img src="'+l+'" alt="Separate persisted history from current launch credentials"></p><p><em>Figure 1. Supplying current values during load and removing old environment fields during save affect different locations. Source: our real temporary-file experiment; diagram by the authors.</em></p><h2 id="reading-an-old-file-does-not-rewrite-it" tabindex="-1">Reading an old file does not rewrite it <a class="header-anchor" href="#reading-an-old-file-does-not-rewrite-it" aria-label="Permalink to &quot;Reading an old file does not rewrite it&quot;">​</a></h2><p>Reading and changing a file are separate operations.</p><p>After reading the old record, the candidate returns an object carrying the current environment. It does not rewrite the original file during that load. Only when we explicitly saved again did the old value disappear from the tested location.</p><p>That matches the proposal&#39;s explanation that the environment field disappears once a record is resaved. An upgrade still leaves a practical question: what happens to old records that are never opened or saved again? If backups retain older copies, who handles them?</p><p>The fix prevented new saves from persisting launch environments and supplied current values on resume. Our experiment clarified the distance between those outcomes and cleaning up every existing copy.</p><h2 id="does-removing-a-copy-make-its-credential-unusable" tabindex="-1">Does removing a copy make its credential unusable? <a class="header-anchor" href="#does-removing-a-copy-make-its-credential-unusable" aria-label="Permalink to &quot;Does removing a copy make its credential unusable?&quot;">​</a></h2><p>That does not follow. “Old” means previously used; it does not mean the service has invalidated the credential. Deleting a local copy does not revoke access.</p><p>Developers therefore need three separate answers:</p><ul><li><strong>Will future saves keep writing it?</strong> Inspect newly saved records.</li><li><strong>What happens to earlier copies?</strong> Assign responsibility for legacy files and backups.</li><li><strong>Have credentials that should no longer work been invalidated?</strong> That requires credential management, not just file deletion.</li></ul><p>Our experiment answers how the tested save and load paths behave. It did not rotate or revoke credentials, or clean backups.</p><p>Users can turn this into a concrete question too: after changing an account or connection, does the application explain what history remains and how old connection material is handled? Successful resume is useful, but it should not create an assumption that every old copy has also been addressed.</p><p>That led to our maintainer question: could upgrade guidance distinguish preventing new persistence from handling existing records, and name the responsibility for the latter? It affects how the fix is used, as well as how its save function is written.</p><details><summary>For technical readers: filtering scope, the fifth control, and limitations</summary><p>Source author: electrumnz. PR #13498 was OPEN when researched. Candidate: <code>bfe7f568976a2c671184722a6e6294927d6e6fae</code>; source baseline: <code>9cfa7fd2d13213b73396cf34b9fc95912857ff69</code>.</p><p>We ran the complete candidate <code>session-store.ts</code>. It wraps the storage interface, removing <code>acpx.session_options.env</code> on save and injecting the current launchEnv on load. Our underlying store used real temporary JSON files. Directly saving the raw record is a negative control, not the complete old ACPX implementation.</p><p>A fifth boundary case deliberately placed the same synthetic value in an unrelated debug field. The candidate removed the designated environment field but retained that arbitrary copy. This tests filtering of a known structure, not general sensitive-value scanning; the artificial field does not establish another production disclosure path.</p><p>Upstream also discusses multiple seats sharing an operating-system account and proposes disabling shell snapshots. We did not reproduce those paths or start a real ACPX child process. Cross-seat access, backup cleanup, credential rotation, and full product resume were not tested. Upstream&#39;s reported 195 tests are not counted as our own execution.</p><p><a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/manual-runs/2026-09-16-current-context" target="_blank" rel="noreferrer">All five observations, probe, and pinned source</a>. This does not establish a corresponding CodeFlowMu disclosure.</p></details><p><a href="https://github.com/joinwell52-AI/joinwell52" target="_blank" rel="noreferrer">Research repository</a></p>',31))])}const w=o(c,[["render",h]]);export{y as __pageData,w as default};
